import java.util.ArrayList;
import java.util.ConcurrentModificationException;
import java.util.List;

/**
 * A DELIBERATE BUG, do not copy: removing from a list inside a for-each over the same list.
 * Run on 2, 3 and 4 elements to show when ConcurrentModificationException appears.
 */
public final class CmeDemo {

    // Private constructor: this class only has static methods (checklist 3.4).
    private CmeDemo() {
    }

    // Runs the same buggy loop on lists of 2, 3 and 4 numbers.
    public static void main(String[] args) {
        int[] sizeArray = {2, 3, 4};

        // one fresh list per size: 1, 2, ..., size
        for (int size : sizeArray) {
            List<Integer> numberList = new ArrayList<>();

            // fill the list
            for (int i = 1; i <= size; i++) {
                numberList.add(i);
            }

            // THE BUG: remove() inside a for-each over the same list
            try {
                for (Integer number : numberList) {
                    // equals, not ==, for an Integer; remove(Object) deletes the value 1
                    if (number.equals(1)) {
                        numberList.remove(number);
                    }
                }

                System.out.printf("n=%d -> no error, left %s%n", size, numberList);
            } catch (ConcurrentModificationException e) {
                // print the exception and go on with the next size
                System.out.printf("n=%d -> %s%n", size, e);
            }
        }
    }
}
